.gzp-desk{
          sfondo:
            gradiente radiale (120% 70% al 50% 0%, rgba (214.178.110,.05), trasparente 58%),
            gradiente radiale (130% 100% al 50% 108%, rgba (0,0,0,.34), trasparente 62%),
            /* venature del legno - spaziate ampiamente e irregolarmente (vecchie linee sottili
               Sembrava velluto) */
            gradiente lineare ripetuto (92 gradi,
              rgba(0,0,0,.13) 0 3px,
              trasparente 3px 17px,
              RGBA(255.255.255.016) 17px 20px,
              trasparente 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              trasparente 43px 74px),
            /* giunti delle tavole */
            gradiente lineare ripetuto (90 gradi,
              rgba(0,0,0,.42) 0 2px,
              trasparente 2px 148px),
            gradiente lineare(180deg, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          posizione: assoluta;
          inserto: 0;
          sfondo: gradiente lineare (180 gradi, #e6d9b6 0%, #d6c599 100%);
          box-ombra: 0 12px 22px rgba(0,0,0,.45), inserto 0 0 0 1px rgba(120,90,36,.2);
          trasformazione: ruota (-1,15 gradi) traduci Y (5px);
        }
        .gzp-under--2{
          sfondo: gradiente lineare (180 gradi, #e1d2ab 0%, #cfbd90 100%);
          trasformazione: ruota(.85deg) traduciY(9px);
        }
